import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

import axios from 'axios';
import { allUserRoute } from '../utils/APIRoutes';
import Contacts from './Contacts';

import '../'

function Chat() {
  const navigate = useNavigate();

  const [contacts, setContacts] = useState([]);
  const [currentUser, setCurrentUser] = useState(undefined);
  const [currentChat, setCurrentchat] = useState(undefined);
  // Use Effect 1
  useEffect(() => {
    async function fetchUser() {
      if (!localStorage.getItem('chaxapp-xchat')) {
        navigate('/login');
      } else {
        setCurrentUser(await JSON.parse(localStorage.getItem('chaxapp-xchat')));
      }
    }
    fetchUser();
  }, []);

  const handleChatChange = (chat) => {
    setCurrentchat(chat)
  }
  // Use Effect 2
  useEffect(() => {
    async function fetchContacts() {
      if (currentUser) {
        if (currentUser.isProfileImageSet) {
          const data = await axios.get(`${allUserRoute}/${currentUser?._id}`);
          setContacts(data?.data);
        } else {
          navigate('/setProfile');
        }
      }
    }
    fetchContacts();
  }, [currentUser]);

  return (
    <div id="chat_component">
      {/* { <img style={ image } src={ currentUser?.profileImage } alt="" /> } */}
      <Contacts contacts={contacts} currentUser={currentUser} changeChat = {handleChatChange} />
    </div>
  );
}

const image = {
  height: '120px',
  width: '120px',
  borderRadius: '50%',
  objectFit: 'cover',
};

export default Chat;
